using System;
using System.Linq;
using System.Collections.Generic;
using System.Runtime.InteropServices;
namespace MonitorSlice {
public static class Ccd {
 [StructLayout(LayoutKind.Sequential)]public struct Luid{public uint Low;public int High;}
 [StructLayout(LayoutKind.Sequential)]public struct Source{public Luid Adapter;public uint Id,Mode,Flags;}
 [StructLayout(LayoutKind.Sequential)]public struct Target{public Luid Adapter;public uint Id,Mode,Technology,Rotation,Scaling,RateN,RateD,Scan,Available,Flags;}
 [StructLayout(LayoutKind.Sequential)]public struct Path{public Source Source;public Target Target;public uint Flags;}
 [StructLayout(LayoutKind.Explicit,Size=64)]public struct Mode{[FieldOffset(0)]public uint Type;[FieldOffset(4)]public uint Id;[FieldOffset(8)]public Luid Adapter;[FieldOffset(16)]public uint Width;[FieldOffset(20)]public uint Height;[FieldOffset(24)]public uint Format;[FieldOffset(28)]public int X;[FieldOffset(32)]public int Y;[FieldOffset(16)]public ulong A;[FieldOffset(24)]public ulong B;[FieldOffset(32)]public ulong C;[FieldOffset(40)]public ulong D;[FieldOffset(48)]public ulong E;[FieldOffset(56)]public ulong F;}
 [StructLayout(LayoutKind.Sequential,CharSet=CharSet.Unicode)]struct Name{public uint Type,Size;public Luid Adapter;public uint Id;[MarshalAs(UnmanagedType.ByValTStr,SizeConst=32)]public string Device;}
 public class State{public Path[] Paths;public Mode[] Modes;}
 [DllImport("user32.dll")]static extern int GetDisplayConfigBufferSizes(uint flags,out uint paths,out uint modes);
 [DllImport("user32.dll")]static extern int QueryDisplayConfig(uint flags,ref uint paths,[In,Out]Path[] pathArray,ref uint modes,[In,Out]Mode[] modeArray,IntPtr topology);
 [DllImport("user32.dll")]static extern int SetDisplayConfig(uint count,Path[] paths,uint modes,Mode[] modeArray,uint flags);
 [DllImport("user32.dll")]static extern int DisplayConfigGetDeviceInfo(ref Name name);
 public static State Read(bool all){for(int retry=0;retry<4;retry++){uint pc,mc;int code=GetDisplayConfigBufferSizes(all?1u:2u,out pc,out mc);if(code!=0)throw new Exception("CCD query sizes: "+code);var ps=new Path[pc];var ms=new Mode[mc];code=QueryDisplayConfig(all?1u:2u,ref pc,ps,ref mc,ms,IntPtr.Zero);if(code==122)continue;if(code!=0)throw new Exception("CCD query: "+code);return new State{Paths=ps.Take((int)pc).ToArray(),Modes=ms.Take((int)mc).ToArray()};}throw new Exception("디스플레이 구성이 변경 중입니다.");}
 static string Device(Path path){var n=new Name{Type=1,Size=(uint)Marshal.SizeOf(typeof(Name)),Adapter=path.Source.Adapter,Id=path.Source.Id};return DisplayConfigGetDeviceInfo(ref n)==0?n.Device:null;}
 public static void Apply(List<Displays.Snapshot> displays){var active=Read(false);var virtualNames=new HashSet<string>(Displays.Virtual().Select(d=>d.Name));var all=Read(true);var paths=new List<Path>();var modes=new List<Mode>();foreach(var display in displays.Where(d=>d.Attached).OrderByDescending(d=>d.Primary)){var candidates=all.Paths.Where(candidate=>candidate.Target.Available!=0&&Device(candidate)==display.Name&&!paths.Any(used=>used.Target.Adapter.Low==candidate.Target.Adapter.Low&&used.Target.Adapter.High==candidate.Target.Adapter.High&&used.Target.Id==candidate.Target.Id)).OrderByDescending(candidate=>(candidate.Flags&1)!=0).ToArray();if(candidates.Length==0)throw new Exception("CCD 경로 없음: "+display.Name);var p=candidates[0];var m=display.Mode;p.Source.Mode=(uint)modes.Count;p.Target.Mode=0xffffffff;p.Flags=1;p.Target.RateN=0;p.Target.RateD=0;p.Target.Scan=0;p.Target.Rotation=1;p.Target.Scaling=1;modes.Add(new Mode{Type=1,Id=p.Source.Id,Adapter=p.Source.Adapter,Width=(uint)m.Width,Height=(uint)m.Height,Format=4,X=m.X,Y=m.Y});if(!virtualNames.Contains(display.Name)){var previous=active.Paths.FirstOrDefault(q=>q.Target.Id==p.Target.Id&&q.Target.Adapter.Low==p.Target.Adapter.Low&&q.Target.Adapter.High==p.Target.Adapter.High);if(previous.Target.Mode<active.Modes.Length){p.Target.RateN=previous.Target.RateN;p.Target.RateD=previous.Target.RateD;p.Target.Scan=previous.Target.Scan;p.Target.Rotation=previous.Target.Rotation;p.Target.Scaling=previous.Target.Scaling;p.Target.Mode=(uint)modes.Count;modes.Add(active.Modes[previous.Target.Mode]);}}paths.Add(p);}System.IO.Directory.CreateDirectory(System.IO.Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"evidence"));System.IO.File.WriteAllText(System.IO.Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"evidence","ccd-plan.json"),new System.Web.Script.Serialization.JavaScriptSerializer().Serialize(new{Requested=displays,Paths=paths,Modes=modes,PathSize=Marshal.SizeOf(typeof(Path)),TargetSize=Marshal.SizeOf(typeof(Target))}));Set(new State{Paths=paths.ToArray(),Modes=modes.ToArray()},true);}
 public static void Set(State state,bool allow){int result=SetDisplayConfig((uint)state.Paths.Length,state.Paths,(uint)state.Modes.Length,state.Modes,0x80|0x20|(allow?0x400u:0u));if(result!=0)throw new Exception("Windows 디스플레이 구성 API 오류: "+result);}
}
}
